  const t = str(text).split('@')[0];
  let m = t.match(/^\/(p|x|a)_?(\d{6,})$/i);
  if (m) return { cmd: { p: 'priority', x: 'unpriority', a: 'applied' }[m[1].toLowerCase()], jobId: m[2] };
  if (/^\/(help|start)$/i.test(t)) return { cmd: 'help' };
  return null;
}

